CREATE OR REPLACE FUNCTION private.org_projection_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb:=to_jsonb(NEW);uid_ text;title_ text;category_ text;status_ text;BEGIN IF NOT private.org_execution_ok() THEN RAISE EXCEPTION 'Projection hors contrat.';END IF;
 IF TG_TABLE_NAME IN ('biz_department_members','biz_team_members','biz_member_affiliations','biz_management_assignments','biz_appointments') THEN uid_:=coalesce(x->>'team_id',x->>'department_id',x->>'system_id');category_:=CASE TG_TABLE_NAME WHEN 'biz_department_members' THEN 'primary' WHEN 'biz_team_members' THEN 'team' WHEN 'biz_member_affiliations' THEN 'concurrent' WHEN 'biz_management_assignments' THEN 'legacy_manager' ELSE 'appointment' END;title_:=x->>'position_id';IF title_ IS NOT NULL AND EXISTS(SELECT 1 FROM org_titles WHERE id=title_ AND unit_id='org-company') THEN uid_:='org-company';END IF;status_:=coalesce(x->>'status','active');
 INSERT INTO org_assignments(id,unit_id,title_id,user_id,category,starts_at,ends_at,status,source,source_id,data) VALUES(x->>'id',uid_,title_,(x->>'user_id')::uuid,category_,(x->>'started_at')::timestamptz,nullif(x->>'ended_at','')::timestamptz,status_,TG_TABLE_NAME,x->>'id',x) ON CONFLICT(id) DO UPDATE SET ends_at=excluded.ends_at,status=excluded.status,data=excluded.data,revision=org_assignments.revision+1;
 ELSIF TG_TABLE_NAME='biz_department_system_history' THEN INSERT INTO org_parent_history(id,unit_id,parent_id,starts_at,ends_at,source,data) VALUES(x->>'id',x->>'department_id',x->>'system_id',(x->>'started_at')::timestamptz,nullif(x->>'ended_at','')::timestamptz,TG_TABLE_NAME,x) ON CONFLICT(id) DO UPDATE SET ends_at=excluded.ends_at,data=excluded.data; END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.biz_legacy_org_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='biz_department_members' THEN IF TG_OP='UPDATE' AND (NEW.ended_at IS DISTINCT FROM OLD.ended_at OR NEW.department_id IS DISTINCT FROM OLD.department_id) THEN UPDATE biz_team_members SET ended_at=coalesce(NEW.ended_at,clock_timestamp()) WHERE user_id=NEW.user_id AND ended_at IS NULL AND team_id IN(SELECT id FROM biz_teams WHERE department_id=OLD.department_id);END IF; ELSE IF NOT NEW.active AND (EXISTS(SELECT 1 FROM biz_teams WHERE department_id=NEW.id AND active) OR EXISTS(SELECT 1 FROM biz_department_members WHERE department_id=NEW.id AND ended_at IS NULL) OR EXISTS(SELECT 1 FROM biz_management_assignments WHERE department_id=NEW.id AND ended_at IS NULL)) THEN RAISE EXCEPTION 'Phòng còn nhóm, thành viên hoặc quản lý hoạt động.';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER org_projection_fence BEFORE INSERT OR UPDATE OR DELETE ON biz_systems FOR EACH ROW EXECUTE FUNCTION private.org_projection_guard();
