REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON biz_systems,biz_departments,biz_teams,biz_positions,biz_appointments,biz_department_members,biz_team_members,biz_member_affiliations,biz_management_assignments,biz_department_system_history,biz_org_events,base_org_state,org_units,org_titles,org_assignments,org_parent_history,org_events FROM PUBLIC,anon,authenticated,service_role;
REVOKE EXECUTE ON FUNCTION biz_org_save(text,jsonb),biz_appointment_save(jsonb),biz_position_save(jsonb),biz_member_save(uuid,uuid,boolean),biz_member_end(uuid),biz_dept_save(uuid,text,text,boolean,integer),base_org_apply(uuid,text),base_org_membership_apply(bigint,jsonb,text),base_org_preview(bigint,jsonb),base_title_roles_save(text,text,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION private.org_projection_sync() FROM PUBLIC,anon,authenticated,service_role;
